INSERT INTO `lesson` (`id`, `title`, `duration`, `course_id`, `section_id`, `video_type`, `cloud_video_id`, `video_url`, `audio_url`, `date_added`, `last_modified`, `lesson_type`, `attachment`, `attachment_type`, `caption`, `summary`, `is_free`, `order`, `quiz_attempt`, `video_type_for_mobile_application`, `video_url_for_mobile_application`, `duration_for_mobile_application`) VALUES
(128, 'Introduction', '00:00:56', 3, 5, 'Vimeo', NULL, 'https://vimeo.com/1107094872', NULL, 1754344800, 1754431200, 'video', '', 'url', NULL, '&lt;p&gt;In this video, we discuss key telecom topics including mobile generation evolution and how cell towers work.&lt;/p&gt;', 1, 0, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:00:56'),
(129, 'Foundational Course Modules', '00:02:25', 3, 5, 'Vimeo', NULL, 'https://vimeo.com/1122451921', NULL, 1754344800, 1765317600, 'video', '', 'url', NULL, '&lt;p&gt;This video covers the foundational course modules in wireless communication, giving you a clear start to understanding wireless networks.&lt;/p&gt;', 1, 0, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:02:25'),
(130, 'Building an Engineer', '00:13:20', 3, 5, 'Vimeo', NULL, 'https://vimeo.com/1122451980', NULL, 1754344800, 1765317600, 'video', '', 'url', NULL, '&lt;p&gt;This video explores building an engineer&#039;s mindset,how to think critically, solve problems, and approach challenges like a true engineer.&lt;/p&gt;', 1, 0, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:13:20'),
(131, 'Telecommunications Domains', '00:10:19', 3, 5, 'vimeo', NULL, 'https://vimeo.com/1107094589', NULL, 1754344800, NULL, 'video', NULL, 'url', NULL, '&lt;p&gt;This video introduces key telecommunication domains, explaining their roles, functions, and how they shape modern communication networks.&lt;/p&gt;', 1, 0, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:10:19'),
(132, ' The Knowledge and Learning Process ', '00:20:29', 3, 5, 'vimeo', NULL, 'https://vimeo.com/1107094756', NULL, 1754344800, NULL, 'video', NULL, 'url', NULL, '&lt;p&gt;This video discusses knowledge and the learning process, exploring how we acquire, process, and apply information effectively.&lt;/p&gt;', 1, 0, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:20:29'),
(133, 'what you need to start', '00:14:12', 3, 6, 'vimeo', NULL, 'https://vimeo.com/1107111074', NULL, 1754344800, NULL, 'video', NULL, 'url', NULL, '&lt;p&gt;What you need to start in a wireless course ,key tools, basic knowledge, and first steps to build a strong foundation in wireless communication.&lt;/p&gt;', 0, 1, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:14:12'),
(134, 'Wireless Communication Basics.1', '00:04:17', 3, 6, 'Vimeo', NULL, 'https://vimeo.com/1107111168', NULL, 1754344800, 1754344800, 'video', '', 'url', NULL, '&lt;p&gt;Learn the basics of wireless communication—key concepts, types, and how it powers modern connectivity. A core topic in our course.&lt;/p&gt;', 0, 2, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:04:17'),
(135, 'Wireless Communication Basics.2', '00:06:59', 3, 6, 'Vimeo', NULL, 'https://vimeo.com/1122452898', NULL, 1754344800, 1765317600, 'video', '', 'url', NULL, '&lt;p&gt;Learn the basics of wireless communication, key concepts, types, and how it powers modern connectivity. A core topic in our course. part2&lt;/p&gt;', 0, 3, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:06:59'),
(136, 'Second Generation', '00:03:54', 3, 6, 'Vimeo', NULL, 'https://vimeo.com/1122453070', NULL, 1754344800, 1765317600, 'video', '', 'url', NULL, '&lt;p&gt;Explore the evolution of 2G technology ,its features, impact, and role in shaping mobile communication. Part of our course series.&lt;/p&gt;', 0, 4, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:03:54'),
(137, 'Third Generation', '00:02:51', 3, 6, 'vimeo', NULL, 'https://vimeo.com/1107107321', NULL, 1754344800, NULL, 'video', NULL, 'url', NULL, '&lt;p&gt;Explore the evolution of3G technology—its features, impact, and role in shaping mobile communication. Part of our course series.&lt;/p&gt;', 0, 5, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:02:51'),
(138, 'Forth Generation', '00:05:33', 3, 6, 'Vimeo', NULL, 'https://vimeo.com/1122452639', NULL, 1754344800, 1765317600, 'video', '', 'url', NULL, '&lt;p&gt;Explore the evolution of 4G technology—its features, impact, and role in shaping mobile communication. Part of our course series.&lt;/p&gt;', 0, 6, 0, 'html5', 'https://www.html5rocks.com/en/tutorials/video/basics/devstories.webm', '00:05:33'),
