(17, 259, '&lt;p&gt;&lt;span lang=&quot;en-AE&quot; style=&quot;font-size:11.0pt;line-height:\r\n107%;font-family:&amp;quot;Calibri&amp;quot;,sans-serif;mso-fareast-font-family:Calibri;\r\nmso-ansi-language:#4C09;mso-fareast-language:EN-US;mso-bidi-language:AR-SA&quot;&gt;What\r\nfactor determines the selection of cable sizes?&lt;/span&gt;&lt;/p&gt;', 'multiple_choice', 3, '[\"losses\",\"speed\",\"Capacity  \"]', '[\"1\"]', 0),
(18, 259, '&lt;p&gt;&lt;span lang=&quot;en-AE&quot; style=&quot;font-size:11.0pt;line-height:\r\n107%;font-family:&amp;quot;Calibri&amp;quot;,sans-serif;mso-fareast-font-family:Calibri;\r\nmso-ansi-language:#4C09;mso-fareast-language:EN-US;mso-bidi-language:AR-SA&quot;&gt;Who\r\nis responsible for monitoring equipment in the communication tower when it\r\nstops working?&lt;/span&gt;&lt;/p&gt;', 'multiple_choice', 3, '[\"Baseband subsystem\",\"Power and environment monitoring\",\"Control subsystem  \"]', '[\"2\"]', 0),
