INSERT INTO `rating` (`id`, `rating`, `user_id`, `ratable_id`, `ratable_type`, `date_added`, `last_modified`, `review`) VALUES
(1, 5, 19, NULL, NULL, 1754984004, NULL, 'A huge amount of reliable and modern scientific and practical information in the science of communication in all its generations while keeping pace with the continuous development and modernization, and I was also pleased to know Engineer Ibrahim and his proximity to the students by meeting weekly. '),
(2, 5, 20, NULL, NULL, 1754985618, NULL, 'A distinguished academy and offers wonderful and very useful courses and the best proof of the right path towards understanding and applying what we have studied in communication engineering and the supervisors of the courses are respected and very wonderful engineers and I loved to follow them with the participants in the courses and facilitate all their affairs, thank you My-Communications and all those in charge of it .'),
(3, 5, 27, NULL, NULL, 1756556330, NULL, 'A rich course in terms of the method of presentation and the way of obtaining information and the most beautiful thing about it is the capable technical team.'),
(4, 5, 28, NULL, NULL, 1756621971, NULL, 'A distinguished course and an excellent explanation from the engineer Ibrahim and an explanation of the practical side in a very large detail, and there is a huge amount of information in this course and the engineers in the academy and those in charge of the courses are very sophisticated, thank you very much'),
(5, 5, 29, NULL, NULL, 1756622296, NULL, 'I was a wonderful thing in the academy, lessons at the top and an explanation that takes away the mind and enjoyable');
